ee:variables.ee:set-variable:
%dw 2.0
output application/json
var keys = payload.Valores map ($.Codigo)
var values = payload.Valores map ($.ValorBase)
---
vars.arrayOfParams << {(keys map '$':upper(values[$$]))}

ee:message.ee:set-payload:
%dw 2.0
output application/json
var tipoSolicitud = vars.responseOrderById.resultados[0].tipoSolicitud default ""
var tipoTramite = vars.responseOrderById.resultados[0].tipoTramite default ""
var nroCoincidencias = vars.arrayOfParams filter (value, index) -> (value.TIPO_SOLICITUD == upper(tipoSolicitud) and value.TIPO_TRAMITE == upper(tipoTramite))
---
 if ( sizeOf(nroCoincidencias) > 0 )
 {
    "tipoSolicitud": tipoSolicitud,
    "tipoTramite": tipoTramite
 }else null

ee:variables.ee:set-variable:
%dw 2.0
output application/xml writeDeclaration=false, skipNullOn="everywhere"
ns ws http://schemas.datacontract.org/2004/07/WS.Gestor.RequestContracts
ns ws1 http://schemas.datacontract.org/2004/07/WS.Gestor.DataContracts
---
ws1#SolicitudesRelacionadas: if (isEmpty(payload.crearSolicitud.solicitudesRelacionadas)) "vacio" else 
	payload.crearSolicitud.solicitudesRelacionadas filter (() -> 
        not isEmpty($.propiedades filter ((item, index) -> item.codigo == p('params.SERVICIO') ))) map ((item, index) -> {
            ws1#descripcion: item.comentarios.comentario,
            ws1#es_principal: do{
                var propsConEsPrincipal = item.propiedades filter ((item, index) -> item.codigo == p('params.esPrincipal'))
                ---
				if(not isEmpty(propsConEsPrincipal)) propsConEsPrincipal[0].valor else null
            },
            ws1#numero_solicitud: item.idOrigen,
            ws1#producto: item.productos.nombre,
            ws1#tipo_solicitud: do{
                var propsConTipoSolicitud = item.propiedades filter ((item, index) -> item.codigo == p('params.tipoSolicitud'))
                ---
                if(not isEmpty(propsConTipoSolicitud)) propsConTipoSolicitud[0].valor else null
            }
        })

ee:message.ee:set-payload:
%dw 2.0
output application/xml encoding= "UTF-8"
import * from dw::util::Values
import * from dw::core::Arrays
import mergeWith from dw::core::Objects

ns soapenv http://schemas.xmlsoap.org/soap/envelope/
ns tem http://tempuri.org/
ns tier http://schemas.datacontract.org/2004/07/Tier.Common
ns ws http://schemas.datacontract.org/2004/07/WS.Gestor.RequestContracts
ns ws1 http://schemas.datacontract.org/2004/07/WS.Gestor.DataContracts
ns sys http://schemas.datacontract.org/2004/07/System.Collections.Generic
ns arr http://schemas.microsoft.com/2003/10/Serialization/Arrays

fun keepGoing(obj, route, valor) = do {
    var newRoute = route -- [route[0]]
    var currentRoute = route[0]
    ---
    if (isEmpty(route)) obj
    else if (obj[currentRoute] == null) obj mergeWith buildBody(route, valor)
    else if (typeOf(obj[currentRoute]) == Object) obj update currentRoute with keepGoing(obj[currentRoute], newRoute, valor)
    else if (typeOf(obj[currentRoute]) == Array) obj
    else obj update currentRoute with valor
}

fun buildBody(ruta, value) = do {
    var currentRuta = ruta[0]
    ---
    if (sizeOf(ruta) > 1) { "$currentRuta": buildBody(slice(ruta, 1, sizeOf(ruta)), value)}
    else {"$currentRuta": value}
}

fun updateProperties(obj, arr) =
    if (sizeOf(arr) > 1)
        do {
            var primerUpdate = updateProperties(obj, arr - arr[0])
            ---
            keepGoing(primerUpdate,arr[0].codigo splitBy ".",arr[0].valor)
        }
    else keepGoing(obj,arr[0].codigo splitBy ".",arr[0].valor)

var properties = vars.responseOrderById.resultados[0].propiedades
var updatedXML = payload update ["Envelope","Body","CrearSolicitud","WSRequestBody"] with updateProperties(payload.Envelope.Body.CrearSolicitud.WSRequestBody, properties)
---
soapenv#Envelope @("xmlns:tem": "http://tempuri.org/",
        "xmlns:tier": "http://schemas.datacontract.org/2004/07/Tier.Common",
        "xmlns:ws": "http://schemas.datacontract.org/2004/07/WS.Gestor.RequestContracts",
        "xmlns:ws1": "http://schemas.datacontract.org/2004/07/WS.Gestor.DataContracts",
        "xmlns:sys": "http://schemas.datacontract.org/2004/07/System.Collections.Generic",
        "xmlns:arr": "http://schemas.microsoft.com/2003/10/Serialization/Arrays"
        ): updatedXML.Envelope

