ee:message.ee:set-payload:
%dw 2.0
output application/xml encoding= "UTF-8"
ns soapenv http://schemas.xmlsoap.org/soap/envelope/
ns tem http://tempuri.org/
ns tier http://schemas.datacontract.org/2004/07/Tier.Common
ns ws http://schemas.datacontract.org/2004/07/WS.Gestor.RequestContracts
ns ws1 http://schemas.datacontract.org/2004/07/WS.Gestor.DataContracts
ns sys http://schemas.datacontract.org/2004/07/System.Collections.Generic
ns arr http://schemas.microsoft.com/2003/10/Serialization/Arrays
var urlRecursos = vars.responseOrderById.resultados[0].urlsRecursos 
            map {
                "codigo": $.codigo,
                "valor": $.valor
            }
var UrlsRecursosSalesforce = payload.crearSolicitud.UrlsRecursosSalesforce map 
            {
                "codigo": $.codigo,
                "valor": $.valor
            }
var validation1 = if (urlRecursos == [] or urlRecursos == null  ) [] else urlRecursos
var validation2 = if (payload.crearSolicitud.productos == null or UrlsRecursosSalesforce == null or UrlsRecursosSalesforce == []   ) [] else UrlsRecursosSalesforce
var idContactosItem = flatten((vars.responseOrderById.resultados[0].items filter ($.idItem == vars.idItem)).contactosItem).id
var contactosMatched = vars.responseOrderById.resultados[0].cliente.contactos filter ((idContactosItem contains($.idContacto)) or upper($.tipoContacto) == "ASESOR COMERCIAL")
---
soapenv#Envelope @("xmlns:tem": "http://tempuri.org/",
        "xmlns:tier": "http://schemas.datacontract.org/2004/07/Tier.Common",
        "xmlns:ws": "http://schemas.datacontract.org/2004/07/WS.Gestor.RequestContracts",
        "xmlns:ws1": "http://schemas.datacontract.org/2004/07/WS.Gestor.DataContracts",
        "xmlns:sys": "http://schemas.datacontract.org/2004/07/System.Collections.Generic",
        "xmlns:arr": "http://schemas.microsoft.com/2003/10/Serialization/Arrays"
        ): {
            soapenv#Header: "",
            soapenv#Body: {
                    tem#CrearSolicitud: {
                            tem#WSRequestHeader: {
                                    tier#property: {
                                            tier#"Scheme_Services.Property": {
                                                    tier#name: null,
                                                    tier#value: null
                                                }
                                        },
                                    tier#system: {
                                            tier#correlationId: vars.responseOrderById.resultados[0].correlationId,
                                            tier#name: null,
                                            tier#processingServer: null
                                        }
                                },
                            tem#WSRequestBody: {
                                    ws#DireccionVentasAsesor:  if (payload.crearSolicitud.productos != null ) (payload.crearSolicitud.DireccionVentasAsesor default "") else "",
                                    ws#AsesorComercial: if(vars.responseOrderById.resultados[0].datosAdicionales.asesorComercial != null and vars.responseOrderById.resultados[0].datosAdicionales.asesorComercial != "") vars.responseOrderById.resultados[0].datosAdicionales.asesorComercial else "",
                                    ws#CiudadInstalacion: payload.crearSolicitud.ciudadInstalacion default "",
                                    ws#ClienteValor: vars.responseOrderById.resultados[0].cliente.valor default "",
                                    ws#CodigoProducto: do{
                                      var productos = ((vars.responseOrderById.resultados[0].items filter $.idItem == payload.crearSolicitud.productos.'ws1:IdItem')[0]).productos
                                      ---
                                      if (!isEmpty(productos)) payload.crearSolicitud.productos."ws1:Codigo" default "" else vars.responseOrderById.resultados[0].datosAdicionales.lineaNegocioPrincipal
                                    },
                                    ws#Comentarios: ( (payload.crearSolicitud.comentarios.comentario default []) ++ (vars.responseOrderById.resultados[0].comentarios.comentario default [])  map ($) )joinBy (" / ") ,
                                    ws#Contactos: {
                                            ws1#Contacto: contactosMatched map {
                                                    ws1#Apellidos: trim(($.primerApellido default "") ++ ($.segundoApellido default "")),
                                                    ws1#CorreoElectronico: $.email default "",
                                                    ws1#Nombres: $.nombres default "",
                                                    ws1#Telefono: $.telefonoFijo default "",
                                                    ws1#TelefonoMovil: $.telefonoMovil default "",
                                                    ws1#Tipo: $.tipoContacto default ""
                                                }
                                        },
                                    ws#CuentaCliente: trim((vars.responseOrderById.resultados[0].cliente.nombres default "") ++ " " ++ (vars.responseOrderById.resultados[0].cliente.primerApellido default "") ++ " " ++ (vars.responseOrderById.resultados[0].cliente.segundoApellido default "")),
                                    ws#DatosViabilidad: {
                                        ws1#DatosAdicionalesViabilidad: {
                                        (sys#KeyValuePairOfstringstring: {
                                            sys#key: "Origen de la campania",
                                            sys#value: vars.responseOrderById.resultados[0].datosAdicionales.campana
                                            }) if (vars.responseOrderById.resultados[0].datosAdicionales.campana != null and vars.responseOrderById.resultados[0].datosAdicionales.campana != ""),
                                        (sys#KeyValuePairOfstringstring: {
                                            sys#key: "Canal externo",
                                            sys#value: vars.responseOrderById.resultados[0].datosAdicionales.canalExterno
                                            }) if (vars.responseOrderById.resultados[0].datosAdicionales.canalExterno != null and vars.responseOrderById.resultados[0].datosAdicionales.canalExterno != ""),
                                        (sys#KeyValuePairOfstringstring: {
                                            sys#key: "Fecha de cierre",
                                            sys#value: vars.responseOrderById.resultados[0].datosAdicionales.fechaCierre
                                            }) if (vars.responseOrderById.resultados[0].datosAdicionales.fechaCierre != null and vars.responseOrderById.resultados[0].datosAdicionales.fechaCierre != ""),
                                        (sys#KeyValuePairOfstringstring: {
                                            sys#key: "Duración Servicio en Dias",
                                            sys#value: vars.responseOrderById.resultados[0].datosAdicionales.duracionDias
                                            }) if (vars.responseOrderById.resultados[0].datosAdicionales.duracionDias != null and vars.responseOrderById.resultados[0].datosAdicionales.duracionDias != ""),
                                        (sys#KeyValuePairOfstringstring: {
                                            sys#key: "Duración Servicio en Meses",
                                            sys#value: vars.responseOrderById.resultados[0].datosAdicionales.duracionMeses
                                            }) if (vars.responseOrderById.resultados[0].datosAdicionales.duracionMeses != null and vars.responseOrderById.resultados[0].datosAdicionales.duracionMeses != ""),
                                        (sys#KeyValuePairOfstringstring: {
                                            sys#key: "Linea de negocio principal",
                                            sys#value: vars.responseOrderById.resultados[0].datosAdicionales.lineaNegocioPrincipal
                                            }) if (vars.responseOrderById.resultados[0].datosAdicionales.lineaNegocioPrincipal != null and vars.responseOrderById.resultados[0].datosAdicionales.lineaNegocioPrincipal != ""),
                                        (sys#KeyValuePairOfstringstring: {
                                            sys#key: "Valor Total Aliado",
                                            sys#value: vars..resultados[0].datosAdicionales.valorTotalAliado
                                            }) if (vars.responseOrderById.resultados[0].datosAdicionales.valorTotalAliado != null and vars.responseOrderById.resultados[0].datosAdicionales.valorTotalAliado != ""),                    
                                        (sys#KeyValuePairOfstringstring: {
                                            sys#key: "Valor Total ETB",
                                            sys#value: vars.responseOrderById.resultados[0].datosAdicionales.valorTotalETB
                                            }) if (vars.responseOrderById.resultados[0].datosAdicionales.valorTotalETB != null and vars.responseOrderById.resultados[0].datosAdicionales.valorTotalETB != ""),
                                        (sys#KeyValuePairOfstringstring: {
                                            sys#key: "Oportunidad",
                                            sys#value: vars.responseOrderById.resultados[0].datosAdicionales.oportunidad
                                            }) if (vars.responseOrderById.resultados[0].datosAdicionales.oportunidad != null and vars.responseOrderById.resultados[0].datosAdicionales.oportunidad != ""),
                                        (sys#KeyValuePairOfstringstring: {
                                            sys#key: "Codigo Oportunidad",
                                            sys#value: vars.responseOrderById.resultados[0].datosAdicionales.codigoOportunidad
                                            }) if (vars.responseOrderById.resultados[0].datosAdicionales.codigoOportunidad != null and vars.responseOrderById.resultados[0].datosAdicionales.codigoOportunidad != ""),
                                        (sys#KeyValuePairOfstringstring: {
                                            sys#key: "target comercial",
                                            sys#value: vars.responseOrderById.resultados[0].datosAdicionales.targetComercial
                                            }) if (vars.responseOrderById.resultados[0].datosAdicionales.targetComercial != null and vars.responseOrderById.resultados[0].datosAdicionales.targetComercial != ""),
                                        (sys#KeyValuePairOfstringstring: {
                                            sys#key: "Ejecutivo de Experiencia",
                                            sys#value: vars.responseOrderById.resultados[0].datosAdicionales.ejecutivoExperiencia
                                            }) if (vars.responseOrderById.resultados[0].datosAdicionales.ejecutivoExperiencia != null and vars.responseOrderById.resultados[0].datosAdicionales.ejecutivoExperiencia != ""),
                                        (sys#KeyValuePairOfstringstring: {
                                            sys#key: "Asesor Comercial",
                                            sys#value: vars.responseOrderById.resultados[0].datosAdicionales.asesorComercial
                                            }) if (vars.responseOrderById.resultados[0].datosAdicionales.asesorComercial != null and vars.responseOrderById.resultados[0].datosAdicionales.asesorComercial != ""),
                                        (sys#KeyValuePairOfstringstring: {
                                            sys#key: "Numero de Caso",
                                            sys#value: vars.responseOrderById.resultados[0].datosAdicionales.numeroCaso
                                            }) if (vars.responseOrderById.resultados[0].datosAdicionales.numeroCaso != null and vars.responseOrderById.resultados[0].datosAdicionales.numeroCaso != ""), 
                                        (payload.crearSolicitud.propiedades map ((item, index) ->
					                        sys#KeyValuePairOfstringstring: {
					                            (sys#key: item.codigo) if(item.codigo != null),
					                            (sys#value: item.valor) if (item.valor != null)
					                        }
					                    ))                    
                                       }
                                    },
                                    ws#DireccionPrincipal: payload.crearSolicitud.direccionPrincipal default '',
                                    (ws#DuracionServicioDias: if (vars.responseOrderById.resultados[0].datosAdicionales.duracionDias != null) vars.responseOrderById.resultados[0].datosAdicionales.duracionDias else null) 
                                        if (vars.responseOrderById.resultados[0].datosAdicionales.duracionDias != null 
                                        and vars.responseOrderById.resultados[0].datosAdicionales.duracionDias != ""),
                                    (ws#DuracionServicioMeses: if (vars.responseOrderById.resultados[0].datosAdicionales.duracionMeses != null) vars.responseOrderById.resultados[0].datosAdicionales.duracionMeses else null) 
                                        if (vars.responseOrderById.resultados[0].datosAdicionales.duracionMeses != null 
                                        and vars.responseOrderById.resultados[0].datosAdicionales.duracionMeses != ""),
                                    ws#EjecutivoExperiencia: if(vars.responseOrderById.resultados[0].datosAdicionales.ejecutivoExperiencia != null and vars.responseOrderById.resultados[0].datosAdicionales.ejecutivoExperiencia != "") vars.responseOrderById.resultados[0].datosAdicionales.ejecutivoExperiencia else "",
                                    ws#Enfoque: vars.responseOrderById.resultados[0].cliente.enfoque default '',
                                    ws#EsquemaAtencion: vars.responseOrderById.resultados[0].cliente.esquemaAtencion default '',
                                    ws#IdViabilidad: if (payload.crearSolicitud.productos != null ) (payload.crearSolicitud.idOrigen default "" ) else "",
                                    ws#IndicadorAgrupacion: if(vars.responseOrderById.resultados[0].datosAdicionales.codigoOportunidad != null and vars.responseOrderById.resultados[0].datosAdicionales.codigoOportunidad != "") vars.responseOrderById.resultados[0].datosAdicionales.codigoOportunidad else "",
                                    ws#Nit: vars.responseOrderById.resultados[0].cliente.numeroDocumento default '',
                                    ws#NombreOperacionComercial: vars.responseOrderById.resultados[0].subAgrupador default '',
                                    ws#NombreOportunidad: if(vars.responseOrderById.resultados[0].datosAdicionales.oportunidad != null and vars.responseOrderById.resultados[0].datosAdicionales.oportunidad != "") vars.responseOrderById.resultados[0].datosAdicionales.oportunidad else "",
                                    ws#NombreProducto: do{
                                      var productos = ((vars.responseOrderById.resultados[0].items filter $.idItem == payload.crearSolicitud.productos.'ws1:IdItem')[0]).productos
                                      ---
                                      if (!isEmpty(productos)) payload.crearSolicitud.productos."ws1:Nombre" default "" else vars.responseOrderById.resultados[0].datosAdicionales.lineaNegocioPrincipal
                                    },
                                    ws#NumeroCaso: if(vars.responseOrderById.resultados[0].datosAdicionales.numeroCaso != null and vars.responseOrderById.resultados[0].datosAdicionales.numeroCaso != "") vars.responseOrderById.resultados[0].datosAdicionales.numeroCaso else "",
                                    ws#NumeroOportunidad: if(vars.responseOrderById.resultados[0].datosAdicionales.codigoOportunidad != null and vars.responseOrderById.resultados[0].datosAdicionales.codigoOportunidad != "") vars.responseOrderById.resultados[0].datosAdicionales.codigoOportunidad else "",
                                    ws#OrdenOM: vars.responseOrderById.resultados[0].ordenOM,
                                    ws#OrigenTransaccion: "MuleSoft",
                                    ws#Prioridad: null,
                                    (ws#Productos: {
                                        ws1#Producto: payload.crearSolicitud.productos
                                    }) if (vars.responseOrderById.resultados[0].items.productos != null),
                                    ws#Segmentacion: vars.responseOrderById.resultados[0].cliente.segmento default '',
                                    ws#Segmento: vars.responseOrderById.resultados[0].cliente.subSegmento default '',
                                    (ws#ServiciosAdicionales: {
                                        arr#string: (payload.crearSolicitud.datosAdicionales filter $.codigo == p('params.ServiciosAdicionales')).valor
                                    }) if((payload.crearSolicitud.datosAdicionales filter $.codigo == p('params.ServiciosAdicionales')).valor != null and payload.crearSolicitud.productos != null ),
                                    ws#SucursalInstalcion: payload.crearSolicitud.sucursalInstalacion default '',
                                    ws#TiempoAns: (payload.crearSolicitud.tiempoAns ) as Number default 0,
                                    ws#TipoInstalacion: payload.crearSolicitud.tipoInstalacion default '',
                                    ws#TipoOperacionPlan: vars.responseOrderById.resultados[0].tipoTramite default '',
                                    ws#TipoOportunidad: vars.responseOrderById.resultados[0].subTipoTramite default '',
                                    ws#TipoSolicitud: vars.responseOrderById.resultados[0].tipoSolicitud default '',
                                    ws#TipologiaVenta: vars.responseOrderById.resultados[0].subTipoSolicitud default '',
                                    ws#UrlsRecursosSalesforce: {
                                            ( (validation1 ++ validation2) map (o, i) -> {
                                                                sys#KeyValuePairOfstringstring @((o.@)): {
                                                                        sys#key: o.codigo,
                                                                        sys#value: o.valor
                                                                    }
                                                            } ) 
                                    },
                                    ws#UsuarioCreacionSalesForce: vars.responseOrderById.resultados[0].usuario default '',
                                    ws#ViabilidadRelacionada: if (payload.crearSolicitud.productos != null ) (payload.crearSolicitud.idOrigen default "" ) else "",
                                    (ws#aplica_rotacion_numerica: if (payload.crearSolicitud.aplica_rotacion_numerica != null) true else null) if (payload.crearSolicitud.aplica_rotacion_numerica != null),
                                    ws#cantidades_tipo_rotacion_numerica: {
                                            sys#KeyValuePairOfstringstring: {
                                                    sys#key: if (payload.crearSolicitud.productos != null)(payload.crearSolicitud.cantidades_tipo_rotacion_numerica[0].codigo default "") else "",
                                                    sys#value: if (payload.crearSolicitud.productos != null)(payload.crearSolicitud.cantidades_tipo_rotacion_numerica[0].valor default "") else ""
                                                }
                                    },
                                    ws#codigo_municipio: payload.crearSolicitud.codigo_municipio default '',
                                    (ws#es_aplica_cobertura: if (payload.crearSolicitud.es_aplica_cobertura != null) true else null) if (payload.crearSolicitud.es_aplica_cobertura != null),
                                    ws#es_direccion_estandar: payload.crearSolicitud.es_direccion_estandar default false,
                                    (ws#solicitudes_relacionadas: vars.solicitudesRelacionadas) if (vars.solicitudesRelacionadas.SolicitudesRelacionadas != "vacio")
                                }
                        }
                }
        }
